begin;

create or replace function public.v515_initialize_2026_2027()
returns jsonb language plpgsql security invoker set search_path=''
as $$
declare v_cycle uuid;v_status text;v_monday uuid;v_thursday uuid;v_friday uuid;v_uid uuid:=auth.uid();begin
 if v_uid is null then raise exception 'authentication required';end if;if not(select private.is_admin()) then return jsonb_build_object('ok',false,'code','FORBIDDEN','message','Accès Admin requis.');end if;
 select id,status into v_cycle,v_status from public.v515_cycles where academic_year='2026/2027' and semester=1 for update;
 if found and (v_status<>'draft' or exists(select 1 from public.v515_requests where cycle_id=v_cycle) or exists(select 1 from public.v515_assignments where cycle_id=v_cycle)) then return jsonb_build_object('ok',false,'code','ALREADY_INITIALIZED','message','Le planning V5.15 existe déjà et contient des données.');end if;
 if v_cycle is null then insert into public.v515_cycles(academic_year,semester,status,group_count,manipulation_count,created_by) values('2026/2027',1,'draft',4,6,v_uid) returning id into v_cycle;else delete from public.v515_sessions where cycle_id=v_cycle;delete from public.v515_groups where cycle_id=v_cycle;delete from public.v515_class_pairs where cycle_id=v_cycle;end if;
 insert into public.v515_class_pairs(cycle_id,weekday,start_time,end_time,class_a,class_b,first_class) values(v_cycle,'monday','13:45','17:30','MPI1-A','MPI1-E','MPI1-A') returning id into v_monday;
 insert into public.v515_class_pairs(cycle_id,weekday,start_time,end_time,class_a,class_b,first_class) values(v_cycle,'thursday','13:30','17:30','MPI1-C','MPI1-D','MPI1-C') returning id into v_thursday;
 insert into public.v515_class_pairs(cycle_id,weekday,start_time,end_time,class_a,class_b,first_class) values(v_cycle,'friday','13:30','17:30','MPI1-B','PC1-A','MPI1-B') returning id into v_friday;
 insert into public.v515_groups(cycle_id,class_name,group_no) select v_cycle,c.class_name,g.group_no from (values('MPI1-A'),('MPI1-E'),('MPI1-C'),('MPI1-D'),('MPI1-B'),('PC1-A')) c(class_name) cross join generate_series(1,4) g(group_no);
 insert into public.v515_sessions(cycle_id,pair_id,session_date,start_time,end_time,class_name,is_teaching_session,non_teaching_reason,effective_session_index,class_occurrence,lifecycle_status,created_by) values
 (v_cycle,v_monday,'2026-09-14','13:45','17:30','MPI1-A',true,null,1,1,'draft',v_uid),(v_cycle,v_monday,'2026-09-21','13:45','17:30','MPI1-E',true,null,2,1,'draft',v_uid),(v_cycle,v_monday,'2026-09-28','13:45','17:30','MPI1-A',true,null,3,2,'draft',v_uid),(v_cycle,v_monday,'2026-10-05','13:45','17:30','MPI1-E',true,null,4,2,'draft',v_uid),(v_cycle,v_monday,'2026-10-12','13:45','17:30','MPI1-A',true,null,5,3,'draft',v_uid),(v_cycle,v_monday,'2026-10-19','13:45','17:30','MPI1-E',true,null,6,3,'draft',v_uid),(v_cycle,v_monday,'2026-10-26','13:45','17:30','MPI1-A',true,null,7,4,'draft',v_uid),(v_cycle,v_monday,'2026-11-02','13:45','17:30',null,false,'REPOS — aucun TP',null,null,'draft',v_uid),(v_cycle,v_monday,'2026-11-09','13:45','17:30','MPI1-E',true,null,8,4,'draft',v_uid),(v_cycle,v_monday,'2026-11-16','13:45','17:30','MPI1-A',true,null,9,5,'draft',v_uid),(v_cycle,v_monday,'2026-11-23','13:45','17:30','MPI1-E',true,null,10,5,'draft',v_uid),(v_cycle,v_monday,'2026-11-30','13:45','17:30','MPI1-A',true,null,11,6,'draft',v_uid),
 (v_cycle,v_thursday,'2026-09-17','13:30','17:30','MPI1-C',true,null,1,1,'draft',v_uid),(v_cycle,v_thursday,'2026-09-24','13:30','17:30','MPI1-D',true,null,2,1,'draft',v_uid),(v_cycle,v_thursday,'2026-10-01','13:30','17:30','MPI1-C',true,null,3,2,'draft',v_uid),(v_cycle,v_thursday,'2026-10-08','13:30','17:30','MPI1-D',true,null,4,2,'draft',v_uid),(v_cycle,v_thursday,'2026-10-15','13:30','17:30',null,false,'JOUR FÉRIÉ — Fête de l''Évacuation — aucun TP',null,null,'draft',v_uid),(v_cycle,v_thursday,'2026-10-22','13:30','17:30','MPI1-C',true,null,5,3,'draft',v_uid),(v_cycle,v_thursday,'2026-10-29','13:30','17:30','MPI1-D',true,null,6,3,'draft',v_uid),(v_cycle,v_thursday,'2026-11-05','13:30','17:30',null,false,'REPOS — aucun TP',null,null,'draft',v_uid),(v_cycle,v_thursday,'2026-11-12','13:30','17:30','MPI1-C',true,null,7,4,'draft',v_uid),(v_cycle,v_thursday,'2026-11-19','13:30','17:30','MPI1-D',true,null,8,4,'draft',v_uid),(v_cycle,v_thursday,'2026-11-26','13:30','17:30','MPI1-C',true,null,9,5,'draft',v_uid),(v_cycle,v_thursday,'2026-12-03','13:30','17:30','MPI1-D',true,null,10,5,'draft',v_uid),
 (v_cycle,v_friday,'2026-09-18','13:30','17:30','MPI1-B',true,null,1,1,'draft',v_uid),(v_cycle,v_friday,'2026-09-25','13:30','17:30','PC1-A',true,null,2,1,'draft',v_uid),(v_cycle,v_friday,'2026-10-02','13:30','17:30','MPI1-B',true,null,3,2,'draft',v_uid),(v_cycle,v_friday,'2026-10-09','13:30','17:30','PC1-A',true,null,4,2,'draft',v_uid),(v_cycle,v_friday,'2026-10-16','13:30','17:30','MPI1-B',true,null,5,3,'draft',v_uid),(v_cycle,v_friday,'2026-10-23','13:30','17:30','PC1-A',true,null,6,3,'draft',v_uid),(v_cycle,v_friday,'2026-10-30','13:30','17:30','MPI1-B',true,null,7,4,'draft',v_uid),(v_cycle,v_friday,'2026-11-06','13:30','17:30',null,false,'REPOS — aucun TP',null,null,'draft',v_uid),(v_cycle,v_friday,'2026-11-13','13:30','17:30','PC1-A',true,null,8,4,'draft',v_uid),(v_cycle,v_friday,'2026-11-20','13:30','17:30','MPI1-B',true,null,9,5,'draft',v_uid),(v_cycle,v_friday,'2026-11-27','13:30','17:30','PC1-A',true,null,10,5,'draft',v_uid),(v_cycle,v_friday,'2026-12-04','13:30','17:30','MPI1-B',true,null,11,6,'draft',v_uid);
 perform private.v515_audit(v_cycle,'planning_initialized',null,'Planning 2026/2027 initialisé depuis les fichiers de référence.','{"rooms_imported":false}'::jsonb);return jsonb_build_object('ok',true,'cycle_id',v_cycle,'status','draft');end; $$;

create or replace function public.v515_publish_cycle(p_cycle_id uuid)
returns jsonb language plpgsql security invoker set search_path=''
as $$ declare v_bad integer;begin
 if auth.uid() is null then raise exception 'authentication required';end if;if not(select private.is_admin()) then return jsonb_build_object('ok',false,'code','FORBIDDEN','message','Accès Admin requis.');end if;
 perform 1 from public.v515_cycles where id=p_cycle_id and status='draft' for update;if not found then return jsonb_build_object('ok',false,'code','INVALID_CYCLE_STATE','message','Ce cycle ne peut pas être publié.');end if;
 select count(*) into v_bad from public.v515_sessions where cycle_id=p_cycle_id and is_teaching_session and(class_occurrence is null or effective_session_index is null or class_name is null);if v_bad>0 then return jsonb_build_object('ok',false,'code','ROTATION_INCONSISTENT','message','Rotation incohérente avec le cycle M1-M6.');end if;
 update public.v515_cycles set status='published',updated_at=now() where id=p_cycle_id;update public.v515_sessions set lifecycle_status='published',updated_at=now() where cycle_id=p_cycle_id and lifecycle_status='draft';perform private.v515_audit(p_cycle_id,'planning_published',null,'Planning publié.','{}'::jsonb);return jsonb_build_object('ok',true,'status','published');end; $$;
revoke execute on function public.v515_initialize_2026_2027() from public,anon;revoke execute on function public.v515_publish_cycle(uuid) from public,anon;grant execute on function public.v515_initialize_2026_2027(),public.v515_publish_cycle(uuid) to authenticated;

commit;
